import React, { useRef, useState } from 'react';
import { Mail, Github, Linkedin, Instagram, ArrowUpRight, Sparkles, ExternalLink, Cloud, Settings, Briefcase } from 'lucide-react';
import { motion } from 'framer-motion';
import { profileData } from '../data/mock';
import { ScrollReveal, StaggeredReveal } from './CloudInfraBackground';

// 3D Tilt Card Component
const TiltCard = ({ children, className = '', glowColor = '#00d4ff' }) => {
  const cardRef = useRef(null);
  const [transform, setTransform] = useState('perspective(1000px) rotateX(0deg) rotateY(0deg)');
  const [glowPosition, setGlowPosition] = useState({ x: 50, y: 50 });

  const handleMouseMove = (e) => {
    if (!cardRef.current || window.innerWidth < 1024) return;

    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    // ... (omitting unchanged logic)
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const rotateX = (y - centerY) / 12;
    const rotateY = (centerX - x) / 12;

    setTransform(`perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`);
    setGlowPosition({ x: (x / rect.width) * 100, y: (y / rect.height) * 100 });
  };

  const handleMouseLeave = () => {
    setTransform('perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)');
    setGlowPosition({ x: 50, y: 50 });
  };

  return (
    <div
      ref={cardRef}
      className={`relative transition-transform duration-300 ease-out ${className}`}
      style={{ transform, transformStyle: 'preserve-3d' }}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      {/* Dynamic glow effect */}
      <div
        className="absolute inset-0 rounded-2xl opacity-0 lg:group-hover:opacity-100 transition-opacity duration-300 pointer-events-none"
        style={{
          background: `radial-gradient(circle at ${glowPosition.x}% ${glowPosition.y}%, ${glowColor}15 0%, transparent 60%)`,
        }}
      />
      {children}
    </div>
  );
};

// Social Link Card with 3D effect
const SocialCard = ({ icon: Icon, name, handle, url, color }) => {
  return (
    <a
      href={url}
      target="_blank"
      rel="noopener noreferrer"
      className="group block"
    >
      <TiltCard glowColor={color}>
        <div
          className="relative bg-[#12121a]/60 backdrop-blur-xl border rounded-2xl p-5 lg:p-6 overflow-hidden transition-all duration-300"
          style={{
            borderColor: `${color}20`,
          }}
        >
          {/* Background gradient */}
          <div
            className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
            style={{
              background: `linear-gradient(135deg, ${color}10 0%, transparent 50%)`
            }}
          />

          {/* Content */}
          <div className="relative z-10 flex items-center gap-4">
            <div
              className="w-10 h-10 lg:w-12 lg:h-12 rounded-lg lg:rounded-xl flex items-center justify-center transition-all duration-500 group-hover:scale-110 group-hover:rotate-6 shadow-xl"
              style={{
                backgroundColor: `${color}15`,
                border: `1px solid ${color}30`,
                boxShadow: `0 0 20px ${color}20`
              }}
            >
              <Icon size={20} style={{ color }} />
            </div>

            <div className="flex-1">
              <h3 className="text-white font-bold text-base lg:text-lg group-hover:gradient-text-cyan transition-all duration-300">
                {name}
              </h3>
              <p className="text-[#6b6b7b] text-[9px] lg:text-[11px] font-mono tracking-tight opacity-70 truncate max-w-[150px] lg:max-w-none">{handle}</p>
            </div>

            <ArrowUpRight
              size={18}
              className="text-[#6b6b7b] group-hover:text-white transition-all duration-500 group-hover:translate-x-1 group-hover:-translate-y-1 opacity-50 group-hover:opacity-100"
            />
          </div>
        </div>
      </TiltCard>
    </a>
  );
};

