import React, { useEffect, useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { useSmoothScroll } from './SmoothScroll';

// Cloud Infrastructure themed floating elements
const CloudInfraBackground = () => {
    const [scrollProgress, setScrollProgress] = useState(0);
    const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
    const lenis = useSmoothScroll();

    useEffect(() => {
        const handleScroll = (e) => {
            // Lenis passes { scroll, limit, velocity, ... }
            const scroll = e?.scroll ?? window.scrollY;
            const scrollHeight = document.documentElement.scrollHeight - window.innerHeight;
            const progress = scroll / scrollHeight;
            setScrollProgress(progress);
        };

        const handleMouseMove = (e) => {
            setMousePos({
                x: (e.clientX / window.innerWidth - 0.5) * 20,
                y: (e.clientY / window.innerHeight - 0.5) * 20
            });
        };

        if (lenis) {
            lenis.on('scroll', handleScroll);
        } else {
            window.addEventListener('scroll', handleScroll, { passive: true });
        }

        window.addEventListener('mousemove', handleMouseMove, { passive: true });

        return () => {
            if (lenis) lenis.off('scroll', handleScroll);
            window.removeEventListener('scroll', handleScroll);
            window.removeEventListener('mousemove', handleMouseMove);
        };
    }, [lenis]);

    // Speed ramping function - slow at edges, fast in middle
    const speedRamp = (progress, section) => {
        const sectionProgress = (progress * 5) - section;
        if (sectionProgress < 0 || sectionProgress > 1) return 0;
        return sectionProgress < 0.5
            ? 4 * sectionProgress * sectionProgress * sectionProgress
            : 1 - Math.pow(-2 * sectionProgress + 2, 3) / 2;
    };

    return (
        <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
            {/* Animated Circuit Board Lines */}
            <svg
                className="absolute inset-0 w-full h-full opacity-10"
                style={{
                    transform: `translate(${mousePos.x * 0.5}px, ${mousePos.y * 0.5}px)`
                }}
            >
                <defs>
                    <linearGradient id="circuit-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#00d4ff" stopOpacity="0" />
                        <stop offset={`${scrollProgress * 100}%`} stopColor="#00d4ff" stopOpacity="1" />
                        <stop offset="100%" stopColor="#ffb800" stopOpacity="0" />
                    </linearGradient>
                    <filter id="glow">
                        <feGaussianBlur stdDeviation="3" result="coloredBlur" />
                        <feMerge>
                            <feMergeNode in="coloredBlur" />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                {[...Array(8)].map((_, i) => (
                    <g key={`h-${i}`} filter="url(#glow)">
                        <path
                            d={`M 0 ${100 + i * 120} H ${200 + (i % 3) * 100} L ${250 + (i % 3) * 100} ${130 + i * 120} H 2000`}
                            stroke="url(#circuit-gradient)"
                            strokeWidth="1"
                            fill="none"
                            style={{
                                strokeDasharray: '1000',
                                strokeDashoffset: 1000 - (scrollProgress * 2000) + (i * 100),
                                transition: 'stroke-dashoffset 0.1s linear'
                            }}
                        />
                    </g>
                ))}

                {/* Vertical circuit lines */}
                {[...Array(6)].map((_, i) => (
                    <g key={`v-${i}`} filter="url(#glow)">
                        <path
                            d={`M ${150 + i * 200} 0 V ${300 + (i % 2) * 200} L ${180 + i * 200} ${350 + (i % 2) * 200} V 2000`}
                            stroke="url(#circuit-gradient)"
                            strokeWidth="1"
                            fill="none"
                            style={{
                                strokeDasharray: '1500',
                                strokeDashoffset: 1500 - (scrollProgress * 3000) + (i * 150),
                                transition: 'stroke-dashoffset 0.1s linear'
                            }}
                        />
                    </g>
                ))}
            </svg>

            {/* Floating Server Nodes */}
            {[...Array(5)].map((_, i) => {
                const baseX = 10 + (i * 20);
                const baseY = 15 + (i * 18);
                const parallaxFactor = 0.3 + (i * 0.15);

                return (
                    <div
                        key={`server-${i}`}
                        className="absolute"
                        style={{
                            left: `${baseX}%`,
                            top: `${baseY}%`,
                            transform: `
                translateY(${scrollProgress * 100 * parallaxFactor}px)
                translateX(${mousePos.x * parallaxFactor}px)
                scale(${0.9 + speedRamp(scrollProgress, i * 0.8) * 0.2})
              `,
                            opacity: 0.2 + speedRamp(scrollProgress, i * 0.8) * 0.4,
                            transition: 'transform 0.8s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.8s ease'
                        }}
                    >
                        <div className="relative">
                            {/* Server rack icon */}
                            <div
                                className="w-10 h-14 rounded border border-[#00d4ff]/30 bg-[#00d4ff]/5 flex flex-col justify-center items-center gap-1 backdrop-blur-sm"
                                style={{
                                    boxShadow: `0 0 ${20 + scrollProgress * 20}px rgba(0, 212, 255, ${0.1 + scrollProgress * 0.1})`
                                }}
                            >
                                <div className="w-6 h-1 bg-[#00d4ff]/50 rounded" />
                                <div className="w-6 h-1 bg-[#00d4ff]/50 rounded" />
                                <div className="w-6 h-1 bg-[#ffb800]/50 rounded" />
                                <div className="w-6 h-1 bg-[#00d4ff]/50 rounded" />
                            </div>
                            {/* Connection lines */}
                            <div
                                className="absolute -right-8 top-1/2 w-8 h-px bg-gradient-to-r from-[#00d4ff]/50 to-transparent"
                                style={{
                                    transform: `scaleX(${speedRamp(scrollProgress, i * 0.8)})`,
                                    transformOrigin: 'left'
                                }}
                            />
                        </div>
                    </div>
                );
            })}

            {/* Cloud Icons with Data Flow */}
            {[...Array(4)].map((_, i) => {
                const positions = [
                    { x: 75, y: 20 },
                    { x: 85, y: 45 },
                    { x: 70, y: 70 },
                    { x: 90, y: 85 }
                ];

                return (
                    <div
                        key={`cloud-${i}`}
                        className="absolute"
                        style={{
                            left: `${positions[i].x}%`,
                            top: `${positions[i].y}%`,
                            transform: `
                translateY(${-scrollProgress * 80 * (0.5 + i * 0.2)}px)
                translateX(${mousePos.x * (0.2 + i * 0.1)}px)
              `,
                            opacity: 0.1 + speedRamp(scrollProgress, i * 0.6) * 0.3,
                            transition: 'transform 0.8s cubic-bezier(0.16, 1, 0.3, 1)'
                        }}
                    >
                        <svg width="48" height="32" viewBox="0 0 48 32" className="fill-none">
                            <path
                                d="M38 28H12C5.4 28 0 22.6 0 16C0 9.4 5.4 4 12 4C12.4 4 12.8 4 13.2 4.1C15.3 1.5 18.5 0 22 0C27.4 0 32 3.8 33.5 9C34.3 8.7 35.1 8.5 36 8.5C41.5 8.5 46 13 46 18.5C46 19.1 45.9 19.6 45.8 20.2C47.1 21.6 48 23.5 48 25.5C48 26.3 47.9 27.2 47.6 28H38Z"
                                stroke="#00d4ff"
                                strokeWidth="1"
                                opacity={0.5 + speedRamp(scrollProgress, i * 0.6) * 0.5}
                            />
                            {/* Data arrows flowing into cloud */}
                            <path
                                d="M24 32 L24 22 M20 26 L24 22 L28 26"
                                stroke="#ffb800"
                                strokeWidth="1.5"
                                style={{
                                    strokeDasharray: '20',
                                    strokeDashoffset: 20 - (scrollProgress * 40),
                                    transition: 'stroke-dashoffset 0.1s linear'
                                }}
                            />
                        </svg>
                    </div>
                );
            })}

            {/* Data Packets floating animation */}
            {[...Array(12)].map((_, i) => {
                const startX = 5 + (i % 4) * 25;
                const startY = (i * 8) % 100;

                return (
                    <div
                        key={`packet-${i}`}
                        className="absolute w-2 h-2 rounded-full"
                        style={{
                            left: `${startX}%`,
                            top: `${startY}%`,
                            background: i % 2 === 0 ? '#00d4ff' : '#ffb800',
                            boxShadow: `0 0 10px ${i % 2 === 0 ? '#00d4ff' : '#ffb800'}`,
                            transform: `
                translateY(${(scrollProgress * 500 + i * 50) % 600 - 100}px)
                translateX(${Math.sin(scrollProgress * 10 + i) * 30}px)
                scale(${0.5 + Math.sin(scrollProgress * 5 + i * 0.5) * 0.5})
              `,
                            opacity: 0.3 + Math.sin(scrollProgress * 8 + i) * 0.2,
                            transition: 'transform 0.1s linear'
                        }}
                    />
                );
            })}

            {/* Kubernetes-like Hexagon Grid */}
            <div
                className="absolute right-0 top-1/4 opacity-5"
                style={{
                    transform: `
            translateY(${scrollProgress * -200}px)
            translateX(${mousePos.x * 0.3}px)
            rotate(${scrollProgress * 30}deg)
          `,
                    transition: 'transform 0.8s cubic-bezier(0.16, 1, 0.3, 1)'
                }}
            >
                <svg width="300" height="300" viewBox="0 0 300 300">
                    {[...Array(7)].map((_, i) => {
                        const row = Math.floor(i / 3);
                        const col = i % 3;
                        const x = 75 + col * 75 + (row % 2) * 37;
                        const y = 75 + row * 65;

                        return (
                            <polygon
                                key={`hex-${i}`}
                                points={`${x},${y - 30} ${x + 26},${y - 15} ${x + 26},${y + 15} ${x},${y + 30} ${x - 26},${y + 15} ${x - 26},${y - 15}`}
                                fill="none"
                                stroke="#00d4ff"
                                strokeWidth="1"
                                style={{
                                    opacity: speedRamp(scrollProgress, i * 0.3),
                                    transform: `scale(${0.8 + speedRamp(scrollProgress, i * 0.3) * 0.2})`,
                                    transformOrigin: `${x}px ${y}px`,
                                    transition: 'all 0.6s ease'
                                }}
                            />
                        );
                    })}
                </svg>
            </div>

            {/* Glowing orbs with parallax */}
            <div
                className="absolute w-[600px] h-[600px] rounded-full"
                style={{
                    left: '-200px',
                    top: '20%',
                    background: 'radial-gradient(circle, rgba(0, 212, 255, 0.08) 0%, transparent 70%)',
                    transform: `
            translateY(${scrollProgress * 300}px)
            translateX(${mousePos.x * 0.5}px)
          `,
                    transition: 'transform 1s cubic-bezier(0.16, 1, 0.3, 1)'
                }}
            />
            <div
                className="absolute w-[500px] h-[500px] rounded-full"
                style={{
                    right: '-150px',
                    bottom: '10%',
                    background: 'radial-gradient(circle, rgba(255, 184, 0, 0.06) 0%, transparent 70%)',
                    transform: `
            translateY(${-scrollProgress * 250}px)
            translateX(${mousePos.x * -0.3}px)
          `,
                    transition: 'transform 1s cubic-bezier(0.16, 1, 0.3, 1)'
                }}
            />
        </div>
    );
};

// Scroll-linked reveal component with cinematic framer-motion transitions
export const ScrollReveal = ({
    children,
    className = '',
    direction = 'up',
    delay = 0,
    duration = 0.8,
    distance = 40,
    once = true
}) => {
    const variants = {
        hidden: {
            opacity: 0,
            y: direction === 'up' ? distance : direction === 'down' ? -distance : 0,
            x: direction === 'left' ? distance : direction === 'right' ? -distance : 0,
            scale: direction === 'zoom' ? 0.95 : 1,
        },
        visible: {
            opacity: 1,
            y: 0,
            x: 0,
            scale: 1,
            transition: {
                duration: duration,
                delay: delay,
                ease: [0.16, 1, 0.3, 1] // Custom easeOutExpo
            }
        }
    };

    return (
        <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once, margin: "-10% 0px -10% 0px" }}
            variants={variants}
            className={className}
        >
            {children}
        </motion.div>
    );
};

// Parallax scroll component
export const ParallaxLayer = ({
    children,
    speed = 0.5,
    className = '',
    rotateOnScroll = false
}) => {
    const [offset, setOffset] = useState(0);
    const [rotation, setRotation] = useState(0);
    const ref = useRef(null);
    const lenis = useSmoothScroll();

    useEffect(() => {
        const handleScroll = (e) => {
            if (!ref.current) return;
            const currentScroll = e?.scroll ?? window.scrollY;
            const rect = ref.current.getBoundingClientRect();
            const scrollProgress = (window.innerHeight - rect.top) / (window.innerHeight + rect.height);

            setOffset(scrollProgress * 100 * speed);
            if (rotateOnScroll) {
                setRotation(scrollProgress * 15);
            }
        };

        if (lenis) {
            lenis.on('scroll', handleScroll);
            handleScroll({ scroll: window.scrollY });
        } else {
            window.addEventListener('scroll', handleScroll, { passive: true });
            handleScroll();
        }

        return () => {
            if (lenis) lenis.off('scroll', handleScroll);
            window.removeEventListener('scroll', handleScroll);
        };
    }, [speed, rotateOnScroll, lenis]);

    return (
        <div
            ref={ref}
            className={className}
            style={{
                transform: `translateY(${offset}px) rotate(${rotation}deg)`,
                transition: 'transform 0.1s linear',
                willChange: 'transform'
            }}
        >
            {children}
        </div>
    );
};

// Staggered reveal for lists/grids using framer-motion
export const StaggeredReveal = ({
    children,
    className = '',
    staggerDelay = 0.1,
    baseDelay = 0,
    once = true
}) => {
    const container = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: staggerDelay,
                delayChildren: baseDelay
            }
        }
    };

    const item = {
        hidden: { opacity: 0, y: 30, scale: 0.98 },
        visible: {
            opacity: 1,
            y: 0,
            scale: 1,
            transition: {
                duration: 0.8,
                ease: [0.16, 1, 0.3, 1]
            }
        }
    };

    return (
        <motion.div
            className={className}
            variants={container}
            initial="hidden"
            whileInView="visible"
            viewport={{ once, margin: "-10% 0px" }}
        >
            {React.Children.map(children, (child) => (
                <motion.div variants={item}>
                    {child}
                </motion.div>
            ))}
        </motion.div>
    );
};

export default CloudInfraBackground;
