import React, { useRef } from 'react';
import { MapPin, Briefcase, GraduationCap, Building2, ChevronRight } from 'lucide-react';
import { motion, useScroll, useSpring, useTransform } from 'framer-motion';
import { journeyData } from '../data/mock';
import { ScrollReveal } from './CloudInfraBackground';

const JourneyCard = ({ item, index, isLeft }) => {
  const getIcon = (type) => {
    switch (type) {
      case 'current-city': return <MapPin size={24} />;
      case 'experience': return <Briefcase size={24} />;
      case 'education': return <GraduationCap size={24} />;
      default: return <Building2 size={24} />;
    }
  };

  const getCityVisualization = () => {
    // ... existing city visualization code ...
    const cities = {
      'Long Beach, CA': {
        buildings: [
          { x: 10, h: 120, w: 30 }, { x: 50, h: 180, w: 40 }, { x: 100, h: 150, w: 35 },
          { x: 145, h: 200, w: 45 }, { x: 200, h: 130, w: 30 }, { x: 240, h: 170, w: 40 }, { x: 290, h: 140, w: 35 },
        ],
        accent: '#00d4ff'
      },
      'Palm Beach Gardens, FL': {
        buildings: [
          { x: 20, h: 100, w: 35 }, { x: 65, h: 160, w: 45 }, { x: 120, h: 130, w: 30 },
          { x: 160, h: 190, w: 50 }, { x: 220, h: 110, w: 35 }, { x: 265, h: 150, w: 40 },
        ],
        accent: '#ffb800'
      },
      'Pune, India': {
        buildings: [
          { x: 15, h: 140, w: 40 }, { x: 65, h: 200, w: 50 }, { x: 125, h: 160, w: 35 },
          { x: 170, h: 220, w: 55 }, { x: 235, h: 130, w: 40 }, { x: 285, h: 180, w: 45 },
        ],
        accent: '#00d4ff'
      }
    };

    const location = item.location || item.title;
    const cityData = cities[location] || cities['Long Beach, CA'];

    return (
      <svg viewBox="0 0 350 250" className="w-full h-full opacity-10">
        <defs>
          <linearGradient id={`grad-${item.id}`} x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor={cityData.accent} stopOpacity="0.3" />
            <stop offset="100%" stopColor={cityData.accent} stopOpacity="0" />
          </linearGradient>
        </defs>
        {cityData.buildings.map((b, i) => (
          <rect
            key={i}
            x={b.x} y={250 - b.h} width={b.w} height={b.h}
            fill={`url(#grad-${item.id})`}
            stroke={cityData.accent}
            strokeWidth="1"
            strokeOpacity="0.3"
          />
        ))}
      </svg>
    );
  };

  return (
    <div className={`relative flex flex-col lg:flex-row items-center mb-16 lg:mb-12 last:mb-0 ${isLeft ? 'lg:flex-row' : 'lg:flex-row-reverse'}`}>

      {/* Content Card */}
      <div className={`w-full lg:w-5/12 ${isLeft ? 'lg:pr-12 lg:text-right' : 'lg:pl-12 lg:text-left'} pl-16 pr-4 lg:px-0`}>
        <ScrollReveal
          direction={isLeft ? 'left' : 'right'}
          delay={0.1}
          className={`relative group bg-[#12121a]/60 backdrop-blur-md border rounded-2xl p-6 lg:p-8 overflow-hidden transition-all duration-500 hover:scale-[1.02] ${item.color === 'cyan'
            ? 'border-[#00d4ff]/20 hover:border-[#00d4ff]/50 hover:shadow-[0_0_40px_rgba(0,212,255,0.1)]'
            : 'border-[#ffb800]/20 hover:border-[#ffb800]/50 hover:shadow-[0_0_40px_rgba(255,184,0,0.1)]'
            }`}
        >
          {/* Decorative City Visualization */}
          <div className="absolute inset-0 pointer-events-none group-hover:opacity-20 transition-opacity duration-500">
            {getCityVisualization()}
          </div>

          <div className="relative z-10">
            {/* Duration Badge */}
            <span className={`inline-block font-mono text-[9px] lg:text-[10px] uppercase tracking-widest px-3 py-1 rounded-full mb-4 ${item.color === 'cyan' ? 'bg-[#00d4ff]/10 text-[#00d4ff]' : 'bg-[#ffb800]/10 text-[#ffb800]'
              }`}>
              {item.duration || item.year}
            </span>

            {/* Title/Company */}
            <h3 className="text-xl lg:text-2xl font-bold text-white mb-1 group-hover:gradient-text-cyan transition-all duration-300">
              {item.company || item.institution || item.title}
            </h3>

            {/* Role/Degree */}
            {(item.role || item.degree) && (
              <p className={`font-medium mb-3 text-base lg:text-lg ${item.color === 'cyan' ? 'text-[#00d4ff]' : 'text-[#ffb800]'
                }`}>
                {item.role || item.degree}
              </p>
            )}

            {/* Divider */}
            <div className={`w-12 h-1 mb-4 rounded-full ${item.color === 'cyan' ? 'bg-[#00d4ff]/30' : 'bg-[#ffb800]/30'} ${isLeft ? 'lg:ml-auto' : 'lg:mr-auto'}`} />

            {/* Location */}
            <div className={`flex items-center gap-2 text-[#6b6b7b] text-xs lg:text-sm mb-6 ${isLeft ? 'lg:justify-end' : 'lg:justify-start'}`}>
              <MapPin size={14} className={item.color === 'cyan' ? 'text-[#00d4ff]' : 'text-[#ffb800]'} />
              <span>{item.location || item.title}</span>
              {item.gpa && (
                <><span>•</span><span className="text-[#00d4ff] font-mono">GPA: {item.gpa}</span></>
              )}
            </div>

            {/* Description or Highlights */}
            {item.description && (
              <p className="text-[#a0a0b0] text-sm lg:text-base mb-6 leading-relaxed opacity-80 group-hover:opacity-100 transition-opacity">
                {item.description}
              </p>
            )}

            {item.highlights && (
              <ul className={`space-y-3 text-[13px] lg:text-sm ${isLeft ? 'lg:text-right' : 'lg:text-left'}`}>
                {item.highlights.slice(0, 4).map((highlight, i) => (
                  <li key={i} className={`flex items-start gap-3 text-[#8a8a9a] group-hover:text-[#a0a0b0] transition-colors ${isLeft ? 'lg:flex-row-reverse' : ''}`}>
                    <div className={`mt-1.5 lg:mt-2 w-1.5 h-1.5 rounded-full flex-shrink-0 ${item.color === 'cyan' ? 'bg-[#00d4ff]' : 'bg-[#ffb800]'}`} />
                    <span>{highlight}</span>
                  </li>
                ))}
              </ul>
            )}

            {/* Tech Stack */}
            {item.techStack && (
              <div className={`flex flex-wrap gap-2 mt-8 ${isLeft ? 'lg:justify-end' : 'lg:justify-start'}`}>
                {item.techStack.map((tech, i) => (
                  <span key={i} className={`px-2 py-1 lg:px-3 lg:py-1 rounded-full text-[9px] lg:text-[10px] font-mono uppercase tracking-wider border border-white/5 bg-white/5 transition-all duration-300 group-hover:border-[#00d4ff]/20 group-hover:text-[#00d4ff]`}>
                    {tech}
                  </span>
                ))}
              </div>
            )}
          </div>
        </ScrollReveal>
      </div>

      {/* Center Icon */}
      <div className="absolute left-6 lg:left-1/2 transform -translate-x-1/2 z-20">
        <ScrollReveal direction="zoom" delay={0.2}>
          <div className={`w-12 h-12 lg:w-16 lg:h-16 rounded-full flex items-center justify-center transition-all duration-500 shadow-2xl ${item.color === 'cyan'
            ? 'bg-[#00d4ff] text-[#0a0a0f] border-4 border-[#0a0a0f] shadow-[0_0_30px_rgba(0,212,255,0.4)]'
            : 'bg-[#ffb800] text-[#0a0a0f] border-4 border-[#0a0a0f] shadow-[0_0_30px_rgba(255,184,0,0.4)]'
            }`}>
            {React.cloneElement(getIcon(item.type), { size: window.innerWidth < 1024 ? 20 : 24 })}
          </div>
        </ScrollReveal>
      </div>

      {/* Empty Space - hidden on mobile */}
      <div className="hidden lg:block w-5/12" />
    </div>
  );
};

const JourneySection = () => {
  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  const scaleY = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  return (
    <section id="journey" ref={containerRef} className="relative py-32 overflow-hidden">
      <div className="max-w-7xl mx-auto px-6 relative">

        {/* Section Header */}
        <ScrollReveal direction="down" className="text-center mb-32">
          <motion.div
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            transition={{ duration: 1 }}
            className="inline-flex items-center gap-2 bg-[#12121a]/80 backdrop-blur-sm border border-[#00d4ff]/20 rounded-full px-4 py-2 mb-6"
          >
            <span className="font-mono text-[10px] text-[#00d4ff] tracking-[0.2em] uppercase">Development Lifecycle</span>
          </motion.div>
          <h2 className="text-5xl md:text-6xl font-bold text-white mb-6 tracking-tight">
            Career <span className="gradient-text-cyan">Timeline</span>
          </h2>
          <p className="text-[#a0a0b0] text-xl max-w-2xl mx-auto opacity-70">
            A chronological visualization of my professional evolution and technical milestones.
          </p>
        </ScrollReveal>

        <div className="relative">
          {/* Vertical Progress Line */}
          <div className="absolute left-6 lg:left-1/2 transform -translate-x-1/2 w-[2px] h-full bg-white/5" />
          <motion.div
            style={{ scaleY }}
            className="absolute left-6 lg:left-1/2 transform -translate-x-1/2 w-[2px] h-full bg-gradient-to-b from-[#00d4ff] via-[#ffb800] to-transparent origin-top z-10"
          />

          <div className="relative space-y-24">
            {journeyData.map((item, index) => (
              <JourneyCard
                key={item.id}
                item={item}
                index={index}
                isLeft={index % 2 === 0}
              />
            ))}
          </div>
        </div>

        {/* Floating Background Glow */}
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full max-w-4xl max-h-4xl bg-gradient-to-r from-[#00d4ff]/5 to-[#ffb800]/5 blur-[120px] rounded-full -z-10 pointer-events-none" />
      </div>
    </section>
  );
};

export default JourneySection;

