import React, { useEffect, useState, useRef } from 'react';
import { ChevronDown, Terminal } from 'lucide-react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';
import { profileData } from '../data/mock';
import ThreeHeroScene from './ThreeHeroScene';

const HeroSection = () => {
  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end start"]
  });

  // Smooth springs for scroll-linked animations
  const smoothY = useSpring(useTransform(scrollYProgress, [0, 1], [0, -100]), { stiffness: 100, damping: 30 });
  const textOpacity = useTransform(scrollYProgress, [0, 0.4], [1, 0]);
  const textMoveX = useTransform(scrollYProgress, [0, 0.4], [0, -50]);

  return (
    <section
      ref={containerRef}
      className="relative min-h-[120vh] flex items-center overflow-hidden bg-[#0a0a0f]"
    >
      {/* 3D WebGL Background */}
      <ThreeHeroScene />

      {/* Vignette Overlay */}
      <div
        className="absolute inset-0 z-[3] pointer-events-none"
        style={{
          background: 'radial-gradient(ellipse at center, transparent 0%, rgba(10, 10, 15, 0.4) 70%, rgba(10, 10, 15, 0.9) 100%)'
        }}
      />

      {/* Main Content Area - Asymmetric Layout */}
      <div className="container mx-auto px-6 relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">

        {/* Left Side: Content */}
        <motion.div
          style={{ opacity: textOpacity, x: textMoveX, y: smoothY }}
          className="max-w-2xl text-center lg:text-left mx-auto lg:mx-0"
        >
          {/* Terminal Badge */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            className="inline-flex items-center gap-2 bg-[#12121a]/90 backdrop-blur-md border border-[#00d4ff]/30 rounded-full px-4 py-2 mb-8"
          >
            <Terminal size={14} className="text-[#00d4ff]" />
            <span className="font-mono text-xs md:text-sm text-[#a0a0b0]">
              <span className="text-[#00d4ff]">~/</span>portfolio<span className="animate-pulse text-[#00d4ff]">_</span>
            </span>
          </motion.div>

          {/* Reveal Heading */}
          <div className="overflow-hidden mb-4">
            <motion.h1
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              transition={{ duration: 1, ease: [0.16, 1, 0.3, 1], delay: 0.2 }}
              className="text-5xl md:text-7xl lg:text-8xl font-bold tracking-tight"
            >
              <span className="text-white block text-3xl md:text-5xl lg:text-6xl mb-2">Hi, I'm</span>
              <span className="gradient-text-cyan text-glow-cyan block leading-tight">
                {profileData.name.split(' ')[0]}
              </span>
            </motion.h1>
          </div>

          {/* Subheading with reveal */}
          <div className="overflow-hidden mb-8">
            <motion.h2
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              transition={{ duration: 1, ease: [0.16, 1, 0.3, 1], delay: 0.4 }}
              className="text-xl md:text-3xl lg:text-4xl font-light text-[#a0a0b0]"
            >
              <span className="text-[#ffb800] relative italic">
                {profileData.title}
                <motion.span
                  initial={{ scaleX: 0 }}
                  animate={{ scaleX: 1 }}
                  transition={{ duration: 1, delay: 1 }}
                  className="absolute -bottom-1 left-0 w-full h-0.5 bg-gradient-to-r from-[#ffb800] to-transparent origin-left"
                />
              </span>
            </motion.h2>
          </div>

          {/* Bio Description */}
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1, ease: [0.16, 1, 0.3, 1], delay: 0.6 }}
            className="text-base md:text-xl text-[#a0a0b0] mb-12 leading-relaxed opacity-90 px-4 md:px-0"
          >
            {profileData.bio}
          </motion.p>

          {/* CTA Group */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1, ease: [0.16, 1, 0.3, 1], delay: 0.8 }}
            className="flex flex-col sm:flex-row items-center justify-center lg:justify-start gap-4"
          >
            <a
              href="#journey"
              className="group relative w-full sm:w-auto px-8 py-4 bg-[#00d4ff] text-[#0a0a0f] font-semibold rounded-full overflow-hidden transition-all duration-300 hover:shadow-[0_0_40px_rgba(0,212,255,0.6)]"
            >
              <span className="relative z-10 flex items-center justify-center gap-2">
                Explore My Journey
                <ChevronDown size={18} className="group-hover:translate-y-1 transition-transform" />
              </span>
              <div className="absolute inset-0 bg-gradient-to-r from-[#00d4ff] to-[#ffb800] opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
            </a>
            <a
              href="#contact"
              className="w-full sm:w-auto px-8 py-4 border-2 border-[#00d4ff]/50 text-[#00d4ff] font-semibold rounded-full hover:bg-[#00d4ff]/10 hover:border-[#00d4ff] hover:shadow-[0_0_30px_rgba(0,212,255,0.3)] transition-all duration-300"
            >
              Get In Touch
            </a>
          </motion.div>
        </motion.div>

        {/* Right Side: Reserved for the floating globe (rendered by ThreeHeroScene) */}
        <div className="hidden lg:block h-screen" />
      </div>

      {/* Background Decorative Elements */}
      <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-[#00d4ff]/5 blur-[120px] rounded-full pointer-events-none -z-1" />
      <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-[#ffb800]/5 blur-[120px] rounded-full pointer-events-none -z-1" />

      {/* Scroll Indicator */}
      <motion.div
        style={{ opacity: textOpacity }}
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2 flex flex-col items-center gap-2 z-10"
      >
        <span className="text-[#6b6b7b] text-xs md:text-sm font-mono opacity-50">Scroll to orbit</span>
        <div className="relative">
          <div className="w-5 h-8 md:w-6 md:h-10 border-2 border-[#00d4ff]/30 rounded-full flex justify-center pt-2">
            <motion.div
              animate={{ y: [0, 6, 0] }}
              transition={{ repeat: Infinity, duration: 1.5 }}
              className="w-1 md:w-1.5 h-2 md:h-3 bg-[#00d4ff]/50 rounded-full"
            />
          </div>
        </div>
      </motion.div>
    </section>
  );
};

export default HeroSection;
