import React, { useRef, useMemo, useState, Suspense, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Points, PointMaterial, Float, Stars } from '@react-three/drei';
import { MathUtils as random } from 'three';
import { useSmoothScroll } from './SmoothScroll';

const CloudPoints = ({ isMobile }) => {
    const ref = useRef();
    const [sphere] = useState(() => {
        const count = isMobile ? 1500 : 3000;
        const positions = new Float32Array(count * 3);
        for (let i = 0; i < count; i++) {
            const x = Math.random() * 2 - 1;
            const y = Math.random() * 2 - 1;
            const z = Math.random() * 2 - 1;
            const mag = Math.sqrt(x * x + y * y + z * z);
            const r = 1.2 + random.randFloat(0, 0.1);

            positions[i * 3] = (x / mag) * r;
            positions[i * 3 + 1] = (y / mag) * r;
            positions[i * 3 + 2] = (z / mag) * r;
        }
        return positions;
    });

    useFrame((state, delta) => {
        if (ref.current) {
            ref.current.rotation.x -= delta / 30;
            ref.current.rotation.y -= delta / 35;
        }
    });

    return (
        <group rotation={[0, 0, Math.PI / 4]}>
            <Points ref={ref} positions={sphere} stride={3} frustumCulled={false}>
                <PointMaterial
                    transparent
                    color="#00d4ff"
                    size={isMobile ? 0.003 : 0.005}
                    sizeAttenuation={true}
                    depthWrite={false}
                    opacity={isMobile ? 0.4 : 0.8}
                />
            </Points>
        </group>
    );
};

const DataPacket = ({ index, isMobile }) => {
    const ref = useRef();
    const speed = 0.5 + Math.random();
    const radius = 1.5 + Math.random() * 0.5;
    const offset = Math.random() * Math.PI * 2;
    const yAxis = Math.random() > 0.5;

    useFrame((state) => {
        const t = state.clock.getElapsedTime() * speed + offset;
        if (ref.current) {
            ref.current.position.x = Math.sin(t) * radius;
            if (yAxis) {
                ref.current.position.y = Math.cos(t) * radius;
                ref.current.position.z = Math.sin(t * 0.5) * 0.5;
            } else {
                ref.current.position.z = Math.cos(t) * radius;
                ref.current.position.y = Math.sin(t * 0.5) * 0.5;
            }
        }
    });

    return (
        <mesh ref={ref}>
            <sphereGeometry args={[0.015, 8, 8]} />
            <meshBasicMaterial
                color={index % 2 === 0 ? "#00d4ff" : "#ffb800"}
                transparent
                opacity={isMobile ? 0.3 : 0.8}
            />
        </mesh>
    );
}

const ServerNodes = ({ isMobile }) => {
    const count = isMobile ? 8 : 15;
    const [positions] = useState(() => {
        const pos = [];
        for (let i = 0; i < count; i++) {
            const x = Math.random() * 2 - 1;
            const y = Math.random() * 2 - 1;
            const z = Math.random() * 2 - 1;
            const mag = Math.sqrt(x * x + y * y + z * z);
            const r = 1.25;
            pos.push([(x / mag) * r, (y / mag) * r, (z / mag) * r]);
        }
        return pos;
    });

    return (
        <group rotation={[0, 0, Math.PI / 4]}>
            {positions.map((pos, i) => (
                <Float key={i} speed={2} rotationIntensity={1} floatIntensity={0.5}>
                    <mesh position={pos}>
                        <boxGeometry args={[0.03, 0.03, 0.03]} />
                        <meshStandardMaterial
                            color={i % 3 === 0 ? "#ffb800" : "#00d4ff"}
                            emissive={i % 3 === 0 ? "#ffb800" : "#00d4ff"}
                            emissiveIntensity={isMobile ? 1 : 2}
                            transparent
                            opacity={isMobile ? 0.6 : 1}
                            toneMapped={false}
                        />
                    </mesh>
                </Float>
            ))}
        </group>
    )
}

const SceneContent = () => {
    const lenis = useSmoothScroll();
    const groupRef = useRef();
    const [scrollProgress, setScrollProgress] = useState(0);
    const [isMobile, setIsMobile] = useState(false);

    useEffect(() => {
        const checkMobile = () => setIsMobile(window.innerWidth < 768);
        checkMobile();
        window.addEventListener('resize', checkMobile);
        return () => window.removeEventListener('resize', checkMobile);
    }, []);

    useFrame((state, delta) => {
        if (!lenis) return;

        const targetProgress = lenis.progress || 0;
        const velocity = lenis.velocity || 0;

        setScrollProgress(prev => prev + (targetProgress - prev) * 0.1);

        if (groupRef.current) {
            if (isMobile) {
                // Mobile: Stays centered, scales down quickly
                const scale = 0.7 - 0.4 * scrollProgress;
                const yPos = -0.2 + 0.5 * scrollProgress; // Moves up slightly
                const zPos = -1.5 * scrollProgress;

                groupRef.current.position.set(0, yPos, zPos);
                groupRef.current.scale.setScalar(scale);
            } else {
                // Desktop: Moves center to right
                const xPos = 0.5 * scrollProgress;
                const scale = 1 - 0.3 * scrollProgress;
                const zPos = -1 * scrollProgress;

                groupRef.current.position.set(xPos, 0, zPos);
                groupRef.current.scale.setScalar(scale);
            }

            groupRef.current.rotation.y += delta * 0.1 + (Math.abs(velocity) * 0.005);
        }
    });

    return (
        <group ref={groupRef}>
            <CloudPoints isMobile={isMobile} />
            <ServerNodes isMobile={isMobile} />
            {[...Array(isMobile ? 10 : 20)].map((_, i) => (
                <DataPacket key={i} index={i} isMobile={isMobile} />
            ))}
        </group>
    );
};

const ThreeHeroScene = () => {
    return (
        <div className="absolute inset-0 z-0 pointer-events-none">
            <Canvas camera={{ position: [0, 0, 2.5], fov: 60 }} dpr={[1, 2]}>
                <Suspense fallback={null}>
                    <ambientLight intensity={0.5} />
                    <pointLight position={[10, 10, 10]} intensity={1} color="#00d4ff" />
                    <pointLight position={[-10, -10, -10]} intensity={0.5} color="#ffb800" />
                    <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />

                    <SceneContent />

                    <OrbitControls
                        enableZoom={false}
                        enablePan={false}
                        autoRotate={false}
                        maxPolarAngle={Math.PI / 1.5}
                        minPolarAngle={Math.PI / 3}
                    />
                </Suspense>
            </Canvas>
        </div>
    );
};

export default ThreeHeroScene;
